    private List<HistoryStoreV20.Item> filtered(boolean favOnly){ArrayList<HistoryStoreV20.Item> o=new ArrayList<>();long day=today();for(HistoryStoreV20.Item i:HistoryStoreV20.get(this)){if(favOnly&&!i.favorite)continue;if(!favOnly){if(filter==1&&i.timestamp<day)continue;if(filter==2&&!i.isWildberries())continue;if(filter==3&&!i.isWatchlist())continue;if(filter==4&&i.dealScore<90)continue;if(filter==5&&!i.favorite)continue;if(filter==6&&i.read)continue;if(filter==7&&!i.isBought())continue;if(filter==8&&!i.isIgnored())continue;}if(!query.isEmpty()&&!i.searchableText().contains(query))continue;o.add(i);}sort(o);return o;}
