    private void analytics(){subpage("Аналитика Intelligence",box->{List<HistoryStoreV20.Item>a=HistoryStoreV20.get(this);int wb=0,fav=0,un=0,watch=0,prio=0,bought=0,ignored=0,best=0,scoreN=0,procN=0;long sav=0,profit=0,proc=0;double scoreSum=0;for(HistoryStoreV20.Item i:a){if(i.isWildberries())wb++;if(i.favorite)fav++;if(!i.read)un++;if(i.isWatchlist())watch++;if(i.dealScore>=90)prio++;if(i.isBought())bought++;if(i.isIgnored())ignored++;if(i.saving>0)sav+=i.saving;if(i.expectedProfit>0)profit+=i.expectedProfit;if(i.dealScore>0){scoreSum+=i.dealScore;scoreN++;best=Math.max(best,i.dealScore);}if(i.processingMs>0){proc+=i.processingMs;procN++;}}box.addView(metric("Всего",a.size()+"",TEXT));box.addView(metric("Watchlist",watch+"",GOLD));box.addView(metric("90+",prio+"",GOLD));box.addView(metric("Wildberries",wb+"",TEXT));box.addView(metric("Непрочитанные",un+"",TEXT));box.addView(metric("Избранные",fav+"",TEXT));box.addView(metric("Средний score",scoreN>0?String.format(Locale.getDefault(),"%.1f/100",scoreSum/scoreN):"—",BLUE));box.addView(metric("Лучший score",best>0?best+"/100":"—",best>=90?GOLD:TEXT));box.addView(metric("Суммарная выгода",sav>0?money((int)Math.min(Integer.MAX_VALUE,sav))+" ₽":"—",GREEN));box.addView(metric("Ожидаемая прибыль",profit>0?money((int)Math.min(Integer.MAX_VALUE,profit))+" ₽":"—",GREEN));box.addView(metric("Куплено",bought+"",GREEN));box.addView(metric("Пропущено",ignored+"",MUTED));box.addView(metric("Средняя обработка",procN>0?formatMs((int)(proc/procN)):"—",BLUE));box.addView(space(10));box.addView(pill("Score, Watchlist, история цен и бизнес-прибыль приходят из Post Finder WB 4.0. Старые записи остаются совместимыми."));});}
