    private void sortSheet(){Dialog d=sheet();LinearLayout p=panel();p.addView(handle(d));String[] n={"Сначала новые","Максимальный score","Максимальная прибыль","Максимальная выгода","Максимальный %","Минимальная цена","Самая быстрая обработка"};for(int i=0;i<n.length;i++){final int m=i;p.addView(sheetRow(sort==i?"✓":"•",n[i],()->{sort=m;d.dismiss();refresh();}));}showSheet(d,p,0);d.show();}
    private void sort(List<HistoryStoreV20.Item>a){Comparator<HistoryStoreV20.Item> c=sort==1?(x,y)->Integer.compare(y.dealScore,x.dealScore):sort==2?(x,y)->Integer.compare(y.expectedProfit,x.expectedProfit):sort==3?(x,y)->Integer.compare(y.saving,x.saving):sort==4?(x,y)->Double.compare(y.discountPercent,x.discountPercent):sort==5?(x,y)->Integer.compare(price(x),price(y)):sort==6?(x,y)->Integer.compare(process(x),process(y)):(x,y)->Long.compare(y.timestamp,x.timestamp);Collections.sort(a,c);}
    private String sortLabel(){String[] n={"Сначала новые","По score","По прибыли","По выгоде","По %","Цена ↑","Скорость ↑"};return n[Math.max(0,Math.min(sort,n.length-1))];}

    private void cycleScore(){int cur=prefs().getInt("min_notify_score",0),next=0;int[] v={0,50,70,80,90};for(int i=0;i<v.length;i++)if(v[i]==cur){next=v[(i+1)%v.length];break;}prefs().edit().putInt("min_notify_score",next).apply();settings();}
    private void toggle(String k){boolean def=!k.equals("compact_cards")&&!k.equals("quiet_mode");prefs().edit().putBoolean(k,!prefs().getBoolean(k,def)).apply();settings();}
    private String backup()throws Exception{JSONObject r=new JSONObject();r.put("schema",3);r.put("app","Post Finder Alerts");r.put("version",version());JSONObject s=new JSONObject();String[] b={"compact_cards","show_processing","auto_update_check","watchlist_bypass_score","auto_favorite_watchlist","quiet_mode","quiet_priority_only"};for(String k:b)s.put(k,prefs().getBoolean(k,!k.equals("compact_cards")&&!k.equals("quiet_mode")));s.put("min_notify_score",prefs().getInt("min_notify_score",0));r.put("settings",s);r.put("history",new JSONObject(HistoryStoreV20.exportJson(this)));return r.toString(2);}
    private void restore(String raw)throws Exception{JSONObject r=new JSONObject(raw),s=r.optJSONObject("settings");if(s!=null){SharedPreferences.Editor e=prefs().edit();for(String k:new String[]{"compact_cards","show_processing","auto_update_check","watchlist_bypass_score","auto_favorite_watchlist","quiet_mode","quiet_priority_only"})if(s.has(k))e.putBoolean(k,s.optBoolean(k));if(s.has("min_notify_score"))e.putInt("min_notify_score",s.optInt("min_notify_score"));e.apply();}JSONObject h=r.optJSONObject("history");if(h!=null)HistoryStoreV20.importJson(this,h.toString());}

    private void checkUpdates(boolean interactive){if(interactive)toast("Проверяю обновление…");new Thread(()->{HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(UPDATE_URL).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(7000);c.connect();if(c.getResponseCode()!=200)throw new Exception();String raw=new String(c.getInputStream().readAllBytes(),StandardCharsets.UTF_8);JSONObject o=new JSONObject(raw);int code=o.optInt("versionCode");String name=o.optString("versionName"),apk=o.optString("apk"),changes=o.optString("changelog");runOnUiThread(()->{if(code>versionCode()&&!apk.isEmpty())updateSheet(name,apk,changes);else if(interactive)toast("Установлена актуальная версия");});}catch(Exception e){runOnUiThread(()->{if(interactive)toast("Не удалось проверить обновление");});}finally{if(c!=null)c.disconnect();}}).start();}
    private void updateSheet(String ver,String apk,String changes){Dialog d=sheet();LinearLayout p=panel();p.addView(handle(d));TextView t=txt("Доступна версия "+ver,20,TEXT,true);t.setGravity(Gravity.CENTER);p.addView(t);TextView c=txt(changes,12,MUTED,false);c.setPadding(dp(4),dp(10),dp(4),dp(12));p.addView(c);TextView u=wide("Скачать обновление",true);u.setOnClickListener(v->{d.dismiss();open(apk);});p.addView(u,new LinearLayout.LayoutParams(-1,dp(50)));showSheet(d,p,0);d.show();}

