    private int price(HistoryStoreV20.Item i){int p=i.effectivePrice>0?i.effectivePrice:i.price;return p>0?p:Integer.MAX_VALUE;}private int process(HistoryStoreV20.Item i){return i.processingMs>0?i.processingMs:Integer.MAX_VALUE;}
    private String status(HistoryStoreV20.Item i){return i.isBought()?"✓ Куплено":i.isIgnored()?"× Пропущено":"Новая находка";}
    private String detailsText(HistoryStoreV20.Item i){StringBuilder b=new StringBuilder(i.displayTitle()).append('\n');if(!i.sourceTitle.isEmpty())b.append("Источник: ").append(i.sourceTitle).append('\n');if(i.dealScore>0)b.append("Score: ").append(i.dealScore).append("/100 ").append(i.scoreLabel).append('\n');if(i.isWatchlist())b.append("Watchlist: ").append(i.watchlistMatch).append('\n');b.append("Статус: ").append(status(i)).append('\n');int e=i.effectivePrice>0?i.effectivePrice:i.price;if(e>0)b.append("Итог: ").append(money(e)).append(" ₽\n");if(i.saving>0)b.append("Выгода: +").append(money(i.saving)).append(" ₽\n");if(i.expectedProfit!=0)b.append("Прибыль: ").append(money(i.expectedProfit)).append(" ₽\n");if(!i.note.isEmpty())b.append("Заметка: ").append(i.note).append('\n');if(!i.link.isEmpty())b.append(i.link).append('\n');return b.toString();}
    private void requestNotifications(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},42);}private boolean notificationsEnabled(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return false;NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);return Build.VERSION.SDK_INT<24||n.areNotificationsEnabled();}
    private void openNotificationSettings(){try{Intent i=new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS);i.putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName());startActivity(i);}catch(Exception e){startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}}
    private void open(String u){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception e){toast("Не удалось открыть ссылку");}}private void copy(String s){((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Post Finder",s));toast("Скопировано");}private void share(String s){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,s);startActivity(Intent.createChooser(i,"Поделиться находкой"));}
    private void createDoc(int r,String name){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,r);}private void openDoc(int r){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");startActivityForResult(i,r);}private void write(Uri u,String s)throws Exception{try(OutputStream o=getContentResolver().openOutputStream(u)){o.write(s.getBytes(StandardCharsets.UTF_8));}}private String read(Uri u)throws Exception{try(InputStream i=getContentResolver().openInputStream(u)){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] x=new byte[8192];int n;while((n=i.read(x))>0)b.write(x,0,n);return b.toString("UTF-8");}}
    private String version(){try{PackageInfo p=getPackageManager().getPackageInfo(getPackageName(),0);return p.versionName;}catch(Exception e){return "2.0";}}private int versionCode(){try{PackageInfo p=getPackageManager().getPackageInfo(getPackageName(),0);return Build.VERSION.SDK_INT>=28?(int)p.getLongVersionCode():p.versionCode;}catch(Exception e){return 0;}}
    private String money(int n){return NumberFormat.getIntegerInstance(Locale.getDefault()).format(n);}private String formatMs(int m){return m<1000?m+" мс":String.format(Locale.getDefault(),"%.1f с",m/1000.0);}private long today(){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}private String time(long t){return new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(t));}private String date(long t){return new SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.getDefault()).format(new Date(t));}private String stamp(){return new SimpleDateFormat("yyyyMMdd-HHmm",Locale.ROOT).format(new Date());}
    private String relative(long t){long s=Math.max(0,(System.currentTimeMillis()-t)/1000);if(s<60)return s<5?"только что":s+" сек назад";long m=s/60;if(m<60)return m+" мин назад";long h=m/60;if(h<24)return h+" ч назад";return h/24+" дн назад";}private String dash(String s){return s==null||s.trim().isEmpty()?"—":s;}private String diagnosticSummary(){long l=AppStateStoreV20.lastSignalTs(this);return l>0?"Последний сигнал • "+relative(l):"Ожидаем первый сигнал";}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    private static final class Menu{final String i,t,s;final Runnable r;Menu(String a,String b,String c,Runnable d){i=a;t=b;s=c;r=d;}}private interface PageBuilder{void build(LinearLayout box);}
